n, a, b, c = map(int, input().split())

# Initialize dp array where dp[i] is the maximum number of pieces for length i
dp = [-1] * (n + 1)
dp[0] = 0  # Base case: 0 length gives 0 pieces

for length in range(1, n + 1):
    for cut in [a, b, c]:
        if length >= cut and dp[length - cut] != -1:
            dp[length] = max(dp[length], dp[length - cut] + 1)

print(dp[n])
"}

