import sys

def main():
    data = sys.stdin.read().strip().split()
    if len(data) != 2:
        print('')
        return
    s1, s2 = data[0], data[1]
    min_login = 'z' * 21  # longer than max possible

    # Generate all non-empty prefixes of first name
    for i in range(1, len(s1) + 1):
        prefix1 = s1[:i]
        # Generate all non-empty prefixes of last name
        for j in range(1, len(s2) + 1):
            prefix2 = s2[:j]
            login = prefix1 + prefix2
            if login < min_login:
                min_login = login

    print(min_login)

if __name__ == '__main__':
    main()
"}

