    # Row 1: 4, 6, 3
    # Row 2: 1, 8, 5

    # This pattern doesn't scale well, let me think of a better approach

    # Better approach: alternate between increasing and decreasing sequences
    current = 2
    for i in range(n):
        for j in range(n):
            if i % 2 == 0:
                # Even row - place even numbers
                matrix[i][j] = current
