import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out_lines = []

    for _ in range(t):
        n = int(next(it))
        k = int(next(it))

        # Create sequence a
        a = []
        for i in range(n):
            if i < k:
                a.append(i + 1)
            else:
                a.append(k - (i - k) - 1)

        # Count frequencies of each value in a
        freq = {}
        for val in a:
            if val not in freq:
                freq[val] = 0
            freq[val] += 1

        # Create list of (value, index) pairs
        value_indices = []
        for idx, val in enumerate(a):
            value_indices.append((val, idx))

        # Sort by value descending, then by index ascending
        value_indices.sort(key=lambda x: (-x[0], x[1]))

        # Build permutation p
        p = [0] * k
        used = [False] * k

        for val, idx in value_indices:
            # Find the largest available value
            largest_val = None
            for i in range(k - 1, -1, -1):
                if not used[i]:
                    largest_val = i
                    break

            # Assign this value to position idx
            p[largest_val] = a[idx]
            used[largest_val] = True

        out_lines.append(' '.join(map(str, p)) + ' ')

    sys.stdout.write('\n'.join(out_lines))

if __name__ == '__main__':
    solve()
