def can_make_palindromic(strings):
    # For each string, determine the character counts for each parity
    # (odd/even positions)
    parities = []
    for s in strings:
        odd_count = 0
        even_count = 0
        for i, ch in enumerate(s):
            if i % 2 == 0:
                odd_count += 1
            else:
                even_count += 1
        parities.append((odd_count, even_count))

    # Now we need to assign characters to each parity group
    # We can treat all odd positions as one group, all even positions as another
    # For each string to be a palindrome, we need all odd positions to have the same character
    # and all even positions to have the same character

    # Count how many strings have the same parity configuration
    parity_count = {}
    for i, (odd, even) in enumerate(parities):
        key = (odd, even)
        parity_count[key] = parity_count.get(key, 0) + 1

    # The answer is the maximum number of strings with the same parity configuration
    # because we can assign characters to those parities to make them palindromes
    # (as long as we can swap freely between strings)

    return max(parity_count.values())

Q = int(input())
for _ in range(Q):
    n = int(input())
    strings = []
    for _ in range(n):
        strings.append(input().strip())

    result = can_make_palindromic(strings)
    print(result)
