def get_doors(char, rotation):
    """Return set of directions block can go in, considering rotation."""

    # Map original character to door directions
    if char == '+':
        return {'up', 'down', 'left', 'right'}
    elif char == '-':
        return {'left', 'right'}
    elif char == '|':
        return {'up', 'down'}
    elif char == '^':
        return {'up'}
    elif char == '>':
        return {'right'}
    elif char == '<':
        return {'left'}
    elif char == 'v':
        return {'down'}
    elif char == 'L':
        return {'up', 'down', 'right'}
    elif char == 'R':
        return {'up', 'down', 'left'}
    elif char == 'U':
        return {'left', 'right', 'down'}
    elif char == 'D':
        return {'left', 'right', 'up'}
    elif char == '*':
        return set()

    # Apply rotation
    rotated = set()
    for dir in get_doors(char, 0):
        if dir == 'up':
            rotated.add('right')
        elif dir == 'right':
            rotated.add('down')
        elif dir == 'down':
            rotated.add('left')
        elif dir == 'left':
            rotated.add('up')

