def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, rank, x, y):
    px = find(parent, x)
    py = find(parent, y)
    if px == py:
        return False
    if rank[px] < rank[py]:
        parent[px] = py
    else:
        parent[py] = px
        if rank[px] == rank[py]:
