    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out_lines = []

    for _ in range(t):
        n, k = int(next(it)), int(next(it))
        a = [int(next(it)) for _ in range(n)]

        # Calculate required x for each element
        x0_counts = {}
        for num in a:
            mod = num % k
            x0 = (k - mod) % k
            if x0 == 0:
                # Already divisible by k
                pass
            else:
                if x0 in x0_counts:
                    x0_counts[x0] += 1
                else:
                    x0_counts[x0] = 1

        # Sort the x0 values
        sorted_x0 = sorted(x0_counts.keys())

        current_x = 0
        total_moves = 0

        for x0 in sorted_x0:
            # Wait for x to reach x0 if needed
            if x0 > current_x:
                wait = x0 - current_x
                total_moves += wait

            # Apply operation 1 to all elements at this x0
            total_moves += x0_counts[x0]

            # Update current_x
            current_x = max(current_x, x0) + 1

        out_lines.append(str(total_moves))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
