    t = int(input())
    for _ in range(t):
        n, k = map(int, input().split())
        # a = [1, 2, ..., k, k-1, k-2, ..., k-(n-k)]
        # Frequency: values 1..k-1 appear twice, value k appears once

        # Create frequency dictionary
        freq = {}
        for i in range(1, k + 1):
            if i < k:
                freq[i] = 2
            else:
                freq[i] = 1

        # Sort values by frequency (descending), then by value (descending) for tie-breaker
        values = sorted(freq.keys(), key=lambda x: (-freq[x], -x))

        # Assign permutation p
        p = {}
        available = list(range(1, k + 1))

        for val in values:
            # Assign largest available to most frequent
            largest = available.pop()
            p[val] = largest

        # Output
        print(' '.join(map(str, [p[i] for i in range(1, k + 1)])) + ' ')

