    i = j = k = -1
    for idx, ch in enumerate(s):
        if ch == '0' and i == -1:
            i = idx
        elif ch == '1' and i != -1 and j == -1:
            j = idx
        elif ch == '0' and i != -1 and j != -1 and k == -1:
