for x, h in trees:
    # Check if we can fell to the left
    can_left = True
    for prev_x, prev_h in trees:
        if prev_x >= x - h and prev_x <= x:
            # Previous tree's position is within the left segment
            can_left = False
            break
    if can_left:
        # Check if any previous segment overlaps
        for prev_x, prev_h in trees:
            if prev_x >= x - h and prev_x <= x:
                can_left = False
                break
        if can_left:
            result += 1
            occupied.add(x - h)
            occupied.add(x)
            continue

    # Check if we can fell to the right
    can_right = True
    for next_x, next_h in trees:
        if next_x >= x and next_x <= x + h:
            # Next tree's position is within the right segment
            can_right = False
            break
    if can_right:
        # Check if any previous segment overlaps
        for prev_x, prev_h in trees:
            if prev_x >= x and prev_x <= x + h:
                can_right = False
                break
        if can_right:
            result += 1
            occupied.add(x)
            occupied.add(x + h)
            continue

    # Leave it standing
    occupied.add(x)

print(result)
