import sys

def create_magic_square(n):
    """Create a magic square of order n (odd)."""
    magic_square = [[0] * n for _ in range(n)]

    # The center cell is n^2 // 2 + 1
    center = n * n // 2 + 1
    magic_square[n//2][n//2] = center

    # Fill the magic square with numbers from 1 to n^2
    # Actually, for odd n, we can use a simple pattern:
    # magic_square[i][j] = i * n + j + 1

    for i in range(n):
        for j in range(n):
            magic_square[i][j] = i * n + j + 1

    return magic_square

def print_magic_square(magic_square):
    for row in magic_square:
        print(' '.join(map(str, row)))

def main():
    n = int(sys.stdin.readline())

    if n == 1:
        print(1)
        return

    magic_square = create_magic_square(n)
    print_magic_square(magic_square)

if __name__ == "__main__":
    main()
