import sys

def create_magic_square(n):
    """Create a magic square of order n (odd)."""
    magic_square = [[0] * n for _ in range(n)]

    # Start at the middle of the top row
    row, col = 0, n // 2

    for number in range(1, n * n + 1):
        magic_square[row][col] = number

        # Move up and right
        row = (row - 1 + n) % n
        col = (col + 1 + n) % n

        # If the cell is already filled, move down one cell
        if magic_square[row][col] != 0:
