    l = list(map(int, input().split()))
    c = list(map(int, input().split()))

    dp = dict()  # key = gcd, value = min cost
    for i in range(n):
        li = l[i]
        ci = c[i]
        # Consider this card alone or combine with existing subsets
        new_dp = {}
        # Add this card as a new subset (empty set + this card)
        new_dp[li] = ci
        # Combine with existing subsets
        for g in dp:
            ng = math.gcd(g, li)
            new_cost = dp[g] + ci
            if ng not in new_dp or new_dp[ng] > new_cost:
                new_dp[ng] = new_cost
        # Merge new_dp into dp
        for g in new_dp:
            if g not in dp or dp[g] > new_dp[g]:
                dp[g] = new_dp[g]

    if 1 in dp:
        print(dp[1])
    else:
        print(-1)

if __name__ == "__main__":
