def gcd(p, q):
    """Calculate the greatest common divisor of p and q"""
    while q:
        p, q = q, p % q
    return p

def lcm(p, q):
    """Calculate the least common multiple of p and q"""
    return p * q // gcd(p, q)

# Find LCM of x and y
lcm_value = lcm(x, y)

# Count multiples of lcm_value in [a, b]
# Smallest multiple >= a: ceil(a / lcm_value) * lcm_value
# Largest multiple <= b: floor(b / lcm_value) * lcm_value
# Count = floor(b / lcm_value) - ceil(a / lcm_value) + 1

first_multiple = ((a + lcm_value - 1) // lcm_value) * lcm_value
last_multiple = (b // lcm_value) * lcm_value

if first_multiple > b:
    print(0)
else:
    print((last_multiple - first_multiple) // lcm_value + 1)
