import math

def count_factor_in_factorial(n, p):
    """Count how many times prime p divides n!"""
    count = 0
    power = p
    while power <= n:
        count += n // power
        power *= p
    return count

def factorize(b):
    """Return prime factors of b as a dictionary"""
    factors = {}

    # Handle 2 separately
    while b % 2 == 0:
        factors[2] = factors.get(2, 0) + 1
        b //= 2

    # Check odd numbers up to sqrt(b)
    i = 3
    while i * i <= b:
        while b % i == 0:
            factors[i] = factors.get(i, 0) + 1
            b //= i
        i += 2

    # If remaining b is prime
    if b > 1:
        factors[b] = factors.get(b, 0) + 1

    return factors

n, b = map(int, input().split())

factors = factorize(b)

if not factors:
    print(0)
else:
    min_trailing_zeros = float('inf')

    for prime, exponent in factors.items():
        count = count_factor_in_factorial(n, prime)
        min_trailing_zeros = min(min_trailing_zeros, count // exponent)

    print(min_trailing_zeros)
"}

