import sys
from bisect import bisect_left, bisect_right

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    a = []
    for _ in range(n):
        a.append(int(next(it)))

    # For each value, store the sorted list of indices where it appears
    value_indices = {}
    for idx, val in enumerate(a):
        if val not in value_indices:
            value_indices[val] = []
        value_indices[val].append(idx + 1)  # 1-indexed

    # Process queries
    output = []
    for _ in range(m):
        l = int(next(it))
        r = int(next(it))

        min_distance = float('inf')

        # Check each value
        for val, indices in value_indices.items():
            # Binary search to find the range of indices in [l, r]
            # Find left bound
            left = bisect_left(indices, l)
            # Find right bound
            right_bound = bisect_right(indices, r)

            # Count of indices in range
            count = right_bound - left

            if count >= 2:
                # Find minimum distance between consecutive indices in this range
                # We can just check consecutive indices
                for i in range(left, right_bound - 1):
                    dist = indices[i+1] - indices[i]
                    if dist < min_distance:
                        min_distance = dist

        if min_distance != float('inf'):
            output.append(str(min_distance))
        else:
            output.append("-1")

    sys.stdout.write("\n".join(output))

if __name__ == "__main__":
    solve()
"}

