import sys
sys.setrecursionlimit(100000)

def solve():
    n, m = map(int, sys.stdin.readline().split())
    cats = list(map(int, sys.stdin.readline().split()))

    # Build adjacency list
    tree = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        x, y = map(int, sys.stdin.readline().split())
        tree[x].append(y)
        tree[y].append(x)

    # Find leaves (vertices with no children except parent)
    # We'll use DFS to count valid leaves

    def dfs(node, parent, consecutive_cats):
        # If we've exceeded m consecutive cats, return 0 valid leaves
        if consecutive_cats > m:
            return 0

        # Check if this is a leaf (no children except parent)
        is_leaf = True
        for neighbor in tree[node]:
            if neighbor != parent:
                is_leaf = False
                break

        if is_leaf:
            return 1 if consecutive_cats <= m else 0

        total = 0
        for neighbor in tree[node]:
            if neighbor != parent:
                # Update consecutive count for child based on current node
                if cats[node - 1] == 1:
                    new_consecutive = consecutive_cats + 1
                else:
                    new_consecutive = 0

                # Check if this path is still valid before exploring
                if new_consecutive <= m:
                    total += dfs(neighbor, node, new_consecutive)
                else:
                    # This path is invalid, don't explore
                    pass

        return total

    result = dfs(1, -1, 0)
    print(result)

solve()
