MOD = 1000000007

n, k = map(int, input().split())

# dp[i][j] = number of good sequences of length i ending with j
dp = [[0] * (n + 1) for _ in range(k + 1)]

# Base case: sequences of length 1
for j in range(1, n + 1):
    dp[1][j] = 1

# Fill DP table
for length in range(2, k + 1):
    for end in range(1, n + 1):
        # Sum over all divisors of end
        total = 0
        for divisor in range(1, end + 1):
            if end % divisor == 0:
                total += dp[length - 1][divisor]
                if total >= MOD:
                    total -= MOD
        dp[length][end] = total % MOD

# Answer is sum of all sequences of length k
result = sum(dp[k][j] for j in range(1, n + 1)) % MOD
print(result)
