# Pre-process: for each value, store the list of indices where it appears
value_indices = {}
for i in range(n):
    val = a[i]
    if val not in value_indices:
        value_indices[val] = []
    value_indices[val].append(i)

# For each query, find the minimum distance between equal elements
for _ in range(m):
    l, r = map(int, input().split())
    # Convert to 0-indexed
    l -= 1
    r -= 1

    min_distance = float('inf')

    # Use a dictionary to track last occurrence of each value within this query
    last_occurrence = {}

    for i in range(l, r + 1):
        val = a[i]
        if val in last_occurrence:
            # This value has appeared before in this query
            distance = abs(i - last_occurrence[val])
            if distance < min_distance:
                min_distance = distance
        # Update last occurrence
        last_occurrence[val] = i

    if min_distance == float('inf'):
        print(-1)
    else:
        print(min_distance)
