from collections import defaultdict, deque

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    m = int(next(it))
    n = int(next(it))

    # For each monster, store its split rules
    splits = defaultdict(list)

    # For each monster, store:
    # - min_diamonds: minimum diamonds to end with no monsters
    # - max_diamonds: maximum diamonds to end with no monsters
    # - has_cycle: whether we can get infinite diamonds (cycle)
    min_diamonds = [-1] * (n + 1)
    max_diamonds = [-1] * (n + 1)
    has_cycle = [False] * (n + 1)

    for _ in range(m):
        mi = int(next(it))
        li = int(next(it))
        rule = []
        for _ in range(li):
            rule.append(int(next(it)))
        splits[mi].append(rule)

    # For each monster, compute min and max diamonds
    for monster in range(1, n + 1):
        # Use BFS to compute minimum diamonds
        # We want to minimize diamonds, so we avoid getting more monsters
        min_queue = deque()
        min_dist = [-1] * (n + 1)
        min_dist[monster] = 0
        min_queue.append(monster)

        while min_queue:
            curr = min_queue.popleft()
            for rule in splits[curr]:
                diamonds = sum(1 for x in rule if x == -1)
                new_monsters = [x for x in rule if x != -1]

                if not new_monsters:
                    # No more monsters, we can stop
                    if min_dist[curr] + diamonds < 0:
                        min_dist[curr] = diamonds
                    continue

                if min_dist[new_monsters[0]] == -1:
                    min_dist[new_monsters[0]] = min_dist[curr] + diamonds
                    min_queue.append(new_monsters[0])

        # Use BFS to compute maximum diamonds
        max_queue = deque()
        max_dist = [-1] * (n + 1)
        max_dist[monster] = 0
        max_queue.append(monster)

        while max_queue:
            curr = max_queue.popleft()
            for rule in splits[curr]:
                diamonds = sum(1 for x in rule if x == -1)
                new_monsters = [x for x in rule if x != -1]

                if not new_monsters:
                    # No more monsters, we can stop
                    if max_dist[curr] + diamonds < 0:
                        max_dist[curr] = diamonds
                    continue

                if max_dist[new_monsters[0]] == -1:
                    max_dist[new_monsters[0]] = max_dist[curr] + diamonds
                    max_queue.append(new_monsters[0])

        # Check for cycles (infinite diamonds)
        # If we can reach a monster that we've already visited and it has monsters,
