    # must be a palindrome, and since (1,1)=1, (i,j) must be 1 if i+j is odd (same parity)
    # and 0 if i+j is even (opposite parity)

    # Construct the grid
    grid = []
    for i in range(1, n + 1):
        row = []
        for j in range(1, n + 1):
            if (i + j) % 2 == 0:
                row.append('1')
            else:
                row.append('0')
        grid.append(''.join(row))

    # Output the solution
    print('!')
    for row in grid:
        print(row)
    sys.stdout.flush()

if __name__ == '__main__':
