import sys

def get_int():
    """Read an integer from stdin, handling empty lines"""
    while True:
        line = sys.stdin.readline().strip()
        if line:
            return int(line)

# Read the grid size
t = get_int()

# Initialize grid
grid = [[0 for _ in range(t)] for _ in range(t)]

# Ask about each cell
for i in range(1, t + 1):
    for j in range(1, t + 1):
        # Ask if there's a palindromic path from (1,1) to (i,j)
        print(f"? 1 1 {i} {j}")
        sys.stdout.flush()

        # Read response
        response = get_int()

        # Set grid value based on response
        if response == 1:
            grid[i - 1][j - 1] = 1
        else:
            grid[i - 1][j - 1] = 0

# Output the result
print("!")
sys.stdout.flush()

# Print the grid
for row in grid:
    print(''.join(map(str, row)))
    sys.stdout.flush()
