    print(f"? 1 1 {i} {t}")
    sys.stdout.flush()

    response = get_int()

    if response == 1:
        # All cells on this row have the same value as (1,1), which is 1
        for j in range(t):
            grid[i - 1][j] = 1
    else:
        # All cells on this row have value 0
        for j in range(t):
            grid[i - 1][j] = 0

