t = int(input())
for _ in range(t):
    n = int(input())
    r = list(map(int, input().split()))
    c = list(map(int, input().split()))

    # Create list of points
    points = list(zip(r, c))

    # Sort by layer r
    points.sort()

    # We can either start with even direction or odd direction
    # Calculate maximum consecutive points we can visit in a row without toggling for both directions

    max_consecutive_even = 1
    max_consecutive_odd = 1

    # Check even direction
    for i in range(1, n):
        r1, c1 = points[i-1]
        r2, c2 = points[i]

        # For even path: from (r1, c1) we go to (r2, c2)
        # This means r2 - r1 = 1 and c2 == c1 (if r1+c1 is even)
        # Or r2 - r1 = 1 and c2 == c1 + 1 (if r1+c1 is odd?)

        # Actually, we need to check if we can go from (r1, c1) to (r2, c2)
        # without toggling

        # If r2 == r1 + 1:
        if r2 == r1 + 1:
            # Adjacent layers
            if r1 % 2 == 0:
                # Even layer: r+c even
                if c2 == c1:
                    max_consecutive_even += 1
                else:
                    break
            else:
                # Odd layer: r+c odd
                if c2 == c1 + 1:
                    max_consecutive_even += 1
                else:
                    break
        else:
            # Not adjacent, can't be in the same row
            break

    # Check odd direction
    for i in range(1, n):
        r1, c1 = points[i-1]
        r2, c2 = points[i]

        # For odd path: from (r1, c1) we go to (r2, c2)
        if r2 == r1 + 1:
            if r1 % 2 == 1:
                # Odd layer: r+c odd
                if c2 == c1 + 1:
                    max_consecutive_odd += 1
                else:
                    break
            else:
                # Even layer: r+c even
                if c2 == c1:
                    max_consecutive_odd += 1
                else:
                    break
        else:
            break

    # Minimum cost = n - 1 - max_consecutive
    # But we also need to account for the first choice of direction
    min_cost = n - 1 - max(max_consecutive_even, max_consecutive_odd)

    print(min_cost)
