from collections import deque

def get_doors(block, rotation):
    """
    Returns a set of directions (up, right, down, left) that the block has doors for
    the given rotation state (0, 1, 2, 3).
    """
    if block == '+':
        return {'up', 'right', 'down', 'left'}
    elif block == '-':
        # Left and right doors
        if rotation == 0:
            return {'left', 'right'}
        elif rotation == 1:
            return {'up', 'down'}
        elif rotation == 2:
            return {'left', 'right'}
        else:  # rotation == 3
            return {'up', 'down'}
    elif block == '|':
        # Up and down doors
        if rotation == 0:
            return {'up', 'down'}
        elif rotation == 1:
            return {'left', 'right'}
        elif rotation == 2:
            return {'up', 'down'}
        else:  # rotation == 3
            return {'left', 'right'}
    elif block == '^':
        # Up door
        if rotation == 0:
            return {'up'}
        elif rotation == 1:
            return {'right'}
        elif rotation == 2:
            return {'down'}
        else:  # rotation == 3
            return {'left'}
    elif block == '>':
        # Right door
        if rotation == 0:
            return {'right'}
        elif rotation == 1:
            return {'down'}
        elif rotation == 2:
            return {'left'}
        else:  # rotation == 3
            return {'up'}
    elif block == '<':
        # Left door
        if rotation == 0:
            return {'left'}
        elif rotation == 1:
            return {'up'}
        elif rotation == 2:
            return {'right'}
        else:  # rotation == 3
            return {'down'}
    elif block == 'v':
        # Down door
        if rotation == 0:
            return {'down'}
        elif rotation == 1:
            return {'left'}
        elif rotation == 2:
            return {'up'}
        else:  # rotation == 3
            return {'right'}
    elif block == 'L':
        # Doors: up, right, down
        if rotation == 0:
            return {'up', 'right', 'down'}
        elif rotation == 1:
            return {'right', 'down', 'left'}
        elif rotation == 2:
            return {'down', 'left', 'up'}
        else:  # rotation == 3
            return {'left', 'up', 'right'}
    elif block == 'R':
        # Doors: up, left, down
        if rotation == 0:
            return {'up', 'left', 'down'}
        elif rotation == 1:
            return {'left', 'down', 'right'}
        elif rotation == 2:
            return {'down', 'right', 'up'}
        else:  # rotation == 3
            return {'right', 'up', 'left'}
    elif block == 'U':
        # Doors: right, down, left
        if rotation == 0:
            return {'right', 'down', 'left'}
        elif rotation == 1:
            return {'down', 'left', 'up'}
        elif rotation == 2:
            return {'left', 'up', 'right'}
        else:  # rotation == 3
            return {'up', 'right', 'down'}
    elif block == 'D':
        # Doors: up, right, left
        if rotation == 0:
            return {'up', 'right', 'left'}
        elif rotation == 1:
            return {'right', 'left', 'down'}
        elif rotation == 2:
            return {'left', 'down', 'up'}
        else:  # rotation == 3
            return {'down', 'up', 'right'}
    elif block == '*':
        return set()


def get_rotated_position(x, y, n, m, rotation):
    """
    Returns the position of the block after rotation.
    """
    if rotation == 0:
        return (x, y)
    elif rotation == 1:
        return (y, n - x + 1)
    elif rotation == 2:
        return (n - x + 1, n - y + 1)
    else:  # rotation == 3
        return (n - y + 1, x)

def solve():
    n, m = map(int, input().split())
    labyrinth = []
    for _ in range(n):
        row = input().strip()
        labyrinth.append(row)

    xT, yT = map(int, input().split())
    xM, yM = map(int, input().split())

    # Convert to 0-indexed coordinates
    xT -= 1
    yT -= 1
    xM -= 1
    yM -= 1

    # BFS
    visited = [None] * 4  # 4 rotation states
    for i in range(4):
        visited[i] = [None] * (n * m)

    q = deque()
    q.append((xT, yT, 0))  # (x, y, rotation)
    visited[0][xT * m + yT] = 0

    answer = -1

    while q:
        x, y, rot = q.popleft()
        time = visited[rot][x * m + y]

        # Try to move to neighboring blocks
        for dx, dy, dir in [(0, -1, 'left'), (0, 1, 'right'), (-1, 0, 'up'), (1, 0, 'down')]:
            nx = x + dx
            ny = y + dy

            # Check if neighbor block has doors that connect
            # Check if current block has a door in the direction of the neighbor
            # Check if neighbor block has a door in the opposite direction
            # But we need to consider the rotation of the neighbor block

            # For the current block (rotated state), does it have a door in the direction of the neighbor?
            current_block = labyrinth[x][y]
            current_doors = get_doors(current_block, rot)
            if dir in current_doors:
                # For the neighbor block, we need to check its rotation state
                # In the current rotation state, the neighbor block's position is (nx, ny)
                # The direction from current block to neighbor is dir
                # The opposite direction is the direction from neighbor to current

                # For the neighbor block to have a door that connects back, it needs to have a door in the opposite direction
                # We need to check if the neighbor block has a door in the opposite direction

                # In the current rotation state, what is the opposite direction of dir for the neighbor?
                # The neighbor block's opposite direction is the direction from neighbor to current

                # In the current rotation state, the direction from neighbor to current is the opposite of dir

                # So we need to check if the neighbor block (with rotation rot) has a door in the opposite direction

                opposite_dir = {'left': 'right', 'right': 'left', 'up': 'down', 'down': 'up'}[dir]
                neighbor_block = labyrinth[nx][ny]
                neighbor_doors = get_doors(neighbor_block, rot)
                if opposite_dir in neighbor_doors:
                    idx = nx * m + ny
                    if visited[rot][idx] is None:
                        visited[rot][idx] = time + 1
                        q.append((nx, ny, rot))
                        if nx == xM and ny == yM:
                            answer = time + 1
                            q = deque()
                            break

        if answer != -1:
            break

        # Try to rotate the labyrinth
        new_rot = (rot + 1) % 4
        if visited[new_rot][x * m + y] is None:
            visited[new_rot][x * m + y] = time + 1
            q.append((x, y, new_rot))
            if x == xM and y == yM and new_rot == 0:
