def solve():
    n, L = map(int, input().split())
    kefa = list(map(int, input().split()))
    sasha = list(map(int, input().split()))

    # Calculate distances between consecutive barriers (including wrap-around)
    def get_distances(sequence):
        distances = []
        for i in range(n):
            dist = sequence[(i + 1) % n] - sequence[i]
            if dist < 0:
                dist += L
            distances.append(dist)
        return distances

    kefa_distances = get_distances(kefa)
    sasha_distances = get_distances(sasha)

    # Check if distances match (up to cyclic permutation)
    # Check if one sequence is a cyclic permutation of the other
    def are_cyclic_permutations(seq1, seq2):
        if len(seq1) != len(seq2):
            return False

        # Check if seq2 is a sublist of seq1 concatenated with itself
        # First, check if the sorted sequences match
        if sorted(seq1) != sorted(seq2):
            return False

