    max_gifts = 0
    best_index = 0

    for i in range(n):
        # If we skip part i+1 (0-indexed), total time is sum of all except a[i]
        total_time = prefix[n] - a[i]

        if total_time <= s:
            gifts = n - 1
        else:
            # Try to recite as many parts as possible
            gifts = 0

            # Recite parts before i
            for k in range(i):
                if prefix[k + 1] <= s:
                    gifts += 1
                else:
                    break

            # Recite parts after i
            if gifts < max_gifts:
                gifts = 0
            l = i + 1
            for k in range(l, n):
                if prefix[k + 1] - prefix[i] <= s - prefix[i + 1]:
                    gifts += 1
                else:
                    break

        if gifts > max_gifts or (gifts == max_gifts and (i + 1) < best_index):
            max_gifts = gifts
            best_index = i + 1

    print(best_index)
