import math

def distance(x, y, px, py):
    return math.sqrt((x - px)**2 + (y - py)**2)

def closest_point_on_segment(px, py, x1, y1, x2, y2):
    """Find closest point on line segment from (x1,y1) to (x2,y2) to point (px,py)"""
    dx = x2 - x1
    dy = y2 - y1

    # Vector from (x1,y1) to (px,py)
    px1 = px - x1
    py1 = py - y1

    # Parametric representation of the line segment
    # t = 0 gives (x1,y1), t = 1 gives (x2,y2)
    t = (px1 * dx + py1 * dy) / (dx*dx + dy*dy)

    if t < 0:
        t = 0
    elif t > 1:
        t = 1

    closest_x = x1 + t * dx
    closest_y = y1 + t * dy

    return closest_x, closest_y, distance(closest_x, closest_y, px, py)

def main():
    n, px, py = map(int, input().split())
    vertices = [tuple(map(int, input().split())) for _ in range(n)]

    max_dist = 0
    min_dist = float('inf')

    # Check vertices
    for x, y in vertices:
        d = distance(x, y, px, py)
        if d > max_dist:
            max_dist = d
        if d < min_dist:
            min_dist = d

    # Check edges
    for i in range(n):
        x1, y1 = vertices[i]
        x2, y2 = vertices[(i+1)%n]

        closest_x, closest_y, closest_d = closest_point_on_segment(px, py, x1, y1, x2, y2)

        if closest_d < min_dist:
            min_dist = closest_d

    area = math.pi * (max_dist**2 - min_dist**2)
    print(area)

if __name__ == "__main__":
    main()
"}

