    x, h = map(int, input().split())
    trees.append((x, h))

# Track occupied positions
occupied = set()
cut_count = 0

# Try to fell trees to the left first (from right to left)
for i in range(n - 1, -1, -1):
    x, h = trees[i]

    # Check if we can fell to the left
    can_fell_left = True
    for pos in range(x - h, x):
        if pos in occupied:
            can_fell_left = False
            break

    if can_fell_left:
        # Fell to the left
        cut_count += 1
        for pos in range(x - h, x):
            occupied.add(pos)
    else:
        # Check if we can fell to the right
        can_fell_right = True
        for pos in range(x, x + h):
            if pos in occupied:
                can_fell_right = False
                break

        if can_fell_right:
            # Fell to the right
            cut_count += 1
            for pos in range(x, x + h):
                occupied.add(pos)
        else:
            # Can't fell, leave standing
            occupied.add(x)

print(cut_count)
