import sys
from collections import Counter

def get_divisors(n):
    """Return a list of all divisors of n"""
    divisors = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    return sorted(divisors)

def solve():
    # Read input
    n = int(sys.stdin.readline())
    divisors_list = list(map(int, sys.stdin.readline().split()))

    # Try all possible pairs (x, y)
    for x_candidate in divisors_list:
        for y_candidate in divisors_list:
            # Find divisors of x_candidate
            x_divisors = get_divisors(x_candidate)

            # Find divisors of y_candidate
            y_divisors = get_divisors(y_candidate)

            # Combine and sort
            combined = sorted(x_divisors + y_divisors)

            # Check if it matches
            if combined == divisors_list:
                print(x_candidate, y_candidate)
                return

if __name__ == "__main__":
    solve()
"}

