MOD = 1000000007

n, k = map(int, input().split())

# dp[i][j] = number of good sequences of length i ending with j
# We'll use a 2D list for dp

dp = [[0] * (n + 1) for _ in range(k + 1)]

# Base case: sequences of length 1
for j in range(1, n + 1):
    dp[1][j] = 1

# Fill dp table
for length in range(2, k + 1):
    for j in range(1, n + 1):
        # Sum of sequences of length-1 ending with divisors of j
        for d in range(1, j + 1):
            if j % d == 0:
                dp[length][j] = (dp[length][j] + dp[length - 1][d]) % MOD

# Sum all sequences of length k
result = sum(dp[k][j] for j in range(1, n + 1)) % MOD

print(result)
