def is_valid(a, b, n):
    """Check if permutation b is valid for array a"""

    # Check all non-empty subsets that are not the full set
    for subset in range(1, (1 << n) - 1):
        # Get indices in subset
        indices = [i for i in range(n) if (subset >> i) & 1]

        # Calculate sum in a and b for this subset
        sum_a = sum(a[i] for i in indices)
        sum_b = sum(b[i] for i in indices)

        if sum_a == sum_b:
            return False
    return True

def backtrack(a, path, used, n):
    """Backtracking to find a valid permutation"""
    if len(path) == n:
        if is_valid(a, path, n):
            return path

    for i in range(n):
        if not used[i]:
            used[i] = True
            result = backtrack(a, path + [a[i]], used, n)
            if result:
                return result
            used[i] = False
    return None

def solve():
    n = int(input())
    a = list(map(int, input().split()))

    # Find a valid permutation using backtracking
    result = backtrack(a, [], [False]*n, n)

    if result:
        print(' '.join(map(str, result)))
    else:
        print(-1)

solve()
