    # Place odd numbers in a way that each row, column, and diagonal has an odd count
    # For odd n, we can use a checkerboard pattern

    # Create an n x n grid
    grid = [[0 for _ in range(n)] for _ in range(n)]

    # Fill grid with numbers from 1 to n^2
    num = 1
    for i in range(n):
        for j in range(n):
            grid[i][j] = num
            num += 1

    # Count of odd numbers we currently have
    odd_count = sum(sum(1 for num in row if num % 2 == 1) for row in grid)

    # We need (n^2 + 1)/2 odd numbers
    required_odds = (n * n + 1) // 2

    # If we have too few odds, we need to add more
    if odd_count < required_odds:
        # Find positions that currently have even numbers and change them to odd
        # We need to make sure we don't double-count the center
        for i in range(n):
            for j in range(n):
