    a, b = map(int, input().split())
    acquainted[a][b] = True
    acquainted[b][a] = True

# Check all possible trios
found = False

# For each person, check all pairs of their acquaintances
for person in range(1, 6):
    # Find all people acquainted with the current person
    friends = [p for p in range(1, 6) if acquainted[person][p]]
    # Check all combinations of 3 friends
    for i in range(len(friends)):
        for j in range(i + 1, len(friends)):
            for k in range(j + 1, len(friends)):
                a, b, c = friends[i], friends[j], friends[k]
                # Check if all three are acquainted
                if acquainted[a][b] and acquainted[a][c] and acquainted[b][c]:
                    found = True
                    break
            if found:
                break
        if found:
            break

    # Check all pairs of non-acquaintances
    non_friends = [p for p in range(1, 6) if not acquainted[person][p] and p != person]
    # Check all combinations of 3 non-acquaintances
    for i in range(len(non_friends)):
        for j in range(i + 1, len(non_friends)):
            for k in range(j + 1, len(non_friends)):
                a, b, c = non_friends[i], non_friends[j], non_friends[k]
                # Check if all three are unacquainted
                if not acquainted[a][b] and not acquainted[a][c] and not acquainted[b][c]:
                    found = True
                    break
            if found:
                break
        if found:
            break

    if found:
        break

print("WIN" if found else "FAIL")
