    # Check all pairs of non-acquaintances of the current person
    non_friends = [p for p in range(1, 6) if not acquainted[person][p] and p != person]
    # Check all combinations of 3 non-acquaintances
    for i in range(len(non_friends)):
        for j in range(i + 1, len(non_friends)):
            for k in range(j + 1, len(non_friends)):
                a, b, c = non_friends[i], non_friends[j], non_friends[k]
                # Check if all three are unacquainted
                if not acquainted[a][b] and not acquainted[a][c] and not acquainted[b][c]:
                    found = True
                    break
            if found:
                break
        if found:
            break

    if found:
        break

print("WIN" if found else "FAIL")

