def note_to_index(note):
    """Map musical note to its position in the cyclic order"""
    note_map = {
        'C': 0, 'C#': 1, 'D': 2, 'D#': 3, 'E': 4,
        'F': 5, 'F#': 6, 'G': 7, 'G#': 8, 'A': 9, 'B': 10, 'H': 11
    }
    return note_map[note]

