is_major = False
is_minor = False

from itertools import permutations

for perm in permutations(indices):
    x, y, z = perm

    # Check major triad: distance x->y = 4, y->z = 3
    dist_xy = (y - x) % 12
    dist_yz = (z - y) % 12
    if dist_xy == 4 and dist_yz == 3:
        is_major = True

    # Check minor triad: distance x->y = 3, y->z = 4
    if dist_xy == 3 and dist_yz == 4:
        is_minor = True

if is_major:
    print("major")
elif is_minor:
    print("minor")
else:
    print("strange")
