    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    groups = list(map(int, data[2:2+n]))

    buses = 0
    current_bus_capacity = 0

    for group in groups:
        if current_bus_capacity + group <= m:
            current_bus_capacity += group
        else:
            buses += 1
            current_bus_capacity = group

    # Add the last bus
    if current_bus_capacity > 0:
        buses += 1

    print(buses)

if __name__ == "__main__":
    solve()
